import java.util.Scanner;

public class Main {
    enum {listName} { {items} }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            int k = sc.nextInt();
            System.out.println("位次 " + k + " 是 " + {listName}.values()[k].name());
        }
        System.out.println("清单上一共 " + {listName}.values().length + " 项");
    }
}
